// Case compatibility index — record JAH-GPCS-PCCASE-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"max_gpu_mm": 400, "fan_slots": 7, "price_usd": 100};
var value = (m.max_gpu_mm*m.fan_slots/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-PCCASE-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-PCCASE-000001|' + value.toFixed(2) + ' compatibility index');

